{
  "a_requests": [
    {
      "a_request": "R1",
      "b_asked": "서울특별시 동물보호 조례상 공원에 반려견 놀이터가 있으면 목줄을 하지 않아도 되는지 여부",
      "c_basis": "APPLIED",
      "d_claims": [
        {
          "a_text": "서울특별시 동물보호 조례 제7조제3항은 등록대상동물을 동반하고 외출할 때 시행규칙 제11조 기준에 맞는 목줄 착용 등 안전조치를 하도록 정하고 있으므로, 공원에 반려견 놀이터가 있다는 사정만으로 목줄을 하지 않아도 된다고 볼 근거는 이 조례에 없다. 반려견 놀이터는 반려 목적으로 기르는 개가 소유자와 함께 목줄 없이 뛰어놀 수 있도록 울타리를 둘러 만든 시설(제2조제14호)로 정의되어 있으나, 이는 놀이터의 개념 정의일 뿐 외출 시 목줄 의무를 면제하는 규정이 아니다. 따라서 놀이터가 있는 공원이라도 등록대상동물을 데리고 외출하는 경우에는 목줄 등 안전조치 의무를 지켜야 한다.",
          "b_ids": "동물보호:제7조제3항, 동물보호:제7조제3항제1호, 동물보호:제2조제14호"
        }
      ],
      "e_status": "ANSWERED"
    }
  ]
}
